create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','staff','admin');
create type public.order_status as enum ('new','accepted','preparing','ready','out_for_delivery','delivered','cancelled');
create table public.users(id uuid primary key references auth.users on delete cascade, role user_role not null default 'customer', name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers(id uuid primary key default gen_random_uuid(), user_id uuid unique references public.users on delete set null, name text not null, whatsapp text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.addresses(id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers on delete cascade, postal_code text not null, street text not null, number text not null, complement text, district text not null, reference text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, sort_order int not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories, name text not null, slug text not null unique, description text not null, ingredients text[] not null default '{}', price numeric(10,2) not null check(price>=0), promotional_price numeric(10,2) check(promotional_price>=0), tag text, available boolean not null default true, active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, storage_path text not null, alt_text text not null, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_options(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, name text not null, required boolean not null default false, min_choices int not null default 0, max_choices int not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_option_items(id uuid primary key default gen_random_uuid(), option_id uuid not null references public.product_options on delete cascade, name text not null, price_delta numeric(10,2) not null default 0, available boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.coupons(id uuid primary key default gen_random_uuid(), code text not null unique, discount_type text not null check(discount_type in ('percent','fixed')), value numeric(10,2) not null check(value>0), starts_at timestamptz, ends_at timestamptz, max_uses int, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.delivery_zones(id uuid primary key default gen_random_uuid(), name text not null unique, fee numeric(10,2) not null check(fee>=0), minimum_order numeric(10,2) not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), number bigint generated always as identity unique, customer_id uuid references public.customers, address_id uuid references public.addresses, status order_status not null default 'new', fulfillment text not null check(fulfillment in ('delivery','pickup')), payment_method text not null check(payment_method in ('pix','cash','card_on_delivery')), subtotal numeric(10,2) not null, delivery_fee numeric(10,2) not null default 0, discount numeric(10,2) not null default 0, total numeric(10,2) not null, coupon_id uuid references public.coupons, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, product_id uuid references public.products, product_name text not null, unit_price numeric(10,2) not null, quantity int not null check(quantity>0), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_item_options(id uuid primary key default gen_random_uuid(), order_item_id uuid not null references public.order_items on delete cascade, option_name text not null, item_name text not null, price_delta numeric(10,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.promotions(id uuid primary key default gen_random_uuid(), name text not null, product_id uuid references public.products, promotional_price numeric(10,2) not null, starts_at timestamptz not null, ends_at timestamptz not null check(ends_at>starts_at), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_hours(id uuid primary key default gen_random_uuid(), weekday smallint not null unique check(weekday between 0 and 6), opens_at time, closes_at time, closed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(), customer_name text not null, rating smallint not null check(rating between 1 and 5), content text not null, source text, approved boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_settings(id uuid primary key default gen_random_uuid(), key text not null unique, value jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index products_category_idx on public.products(category_id,active,sort_order);create index orders_status_created_idx on public.orders(status,created_at desc);create index orders_customer_idx on public.orders(customer_id);create index addresses_customer_idx on public.addresses(customer_id);create index promotion_window_idx on public.promotions(active,starts_at,ends_at);
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.users where id=auth.uid() and role in ('admin','staff')) $$;
alter table public.users enable row level security;alter table public.customers enable row level security;alter table public.addresses enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_images enable row level security;alter table public.product_options enable row level security;alter table public.product_option_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.order_item_options enable row level security;alter table public.coupons enable row level security;alter table public.promotions enable row level security;alter table public.delivery_zones enable row level security;alter table public.business_hours enable row level security;alter table public.reviews enable row level security;alter table public.site_settings enable row level security;
create policy "public reads catalog" on public.products for select using(active);create policy "public reads categories" on public.categories for select using(active);create policy "public reads images" on public.product_images for select using(true);create policy "public reads approved reviews" on public.reviews for select using(approved);create policy "admins manage products" on public.products for all using(public.is_admin()) with check(public.is_admin());create policy "admins manage orders" on public.orders for all using(public.is_admin()) with check(public.is_admin());create policy "customers read orders" on public.orders for select using(customer_id in(select id from public.customers where user_id=auth.uid()));
